 a=ast.parse((r/native).read_text()); b=ast.parse((r/frozen).read_text())
 def signatures(t):
  return {n.name:ast.dump(n,include_attributes=False) for n in t.body if isinstance(n,(ast.FunctionDef,ast.ClassDef)) and n.name"'!='"'Model'}
 assert signatures(a)==signatures(b)
