 rep=copy.deepcopy(mb['_represent'])
 cuts=[n for n in rep.body if isinstance(n,ast.If) and isinstance(n.test,ast.Compare) and isinstance(n.test.left,ast.Attribute) and n.test.left.attr=='action_codebook_gradient']
