  (isinstance(n,ast.If) and isinstance(n.test,ast.Compare) and isinstance(n.test.left,ast.Name) and n.test.left.id=='action_codebook_gradient') or
  (isinstance(n,ast.Assign) and any(isinstance(t,ast.Attribute) and t.attr=='action_codebook_gradient' for t in n.targets)))]
